//! What each mode reaches of each part of a project, as the settings' Who
//! can see what grid shows it: worked out from the profiles as they compile
//! now, so it follows the classification and the Spec tasks switches.

use std::path::{Path, PathBuf};

use super::{Access, Classification, Compiled, ProfileKind, Rule, RunFiles, compile, profile, relative};

/// The parts of a project the grid shows each mode's reach into.
