        ProfileKind::Freeform => "freeform",
        ProfileKind::Bare => "bare",
    }
}

/// The levels a project sets, by mode and area, as `.suspense/sandbox.json`
/// keeps them.
pub type Levels = BTreeMap<String, BTreeMap<String, Level>>;

/// Whether `kind` may be given `level` in `area`, as the SandboxScope says:
/// never past what the sandbox allows. With why not.
pub fn allowed(kind: ProfileKind, area: Area, level: Level) -> Result<(), &'static str> {
    match (kind, area, level) {
        (ProfileKind::Code, Area::SpecSource, Level::Edit | Level::Read) => {
            Err("The separation of code and spec is never relaxed: a Code run can't open the spec's source.")
        }
        (ProfileKind::Spec, Area::Code, Level::Edit) => {
            Err("The separation of code and spec is never relaxed: a Spec run can't change the code.")
        }
        (ProfileKind::Question, _, Level::Edit) => Err("Ask never changes anything."),
        (_, Area::ProjectData, Level::Edit) => Err("No run may change the project's data."),
        _ => Ok(()),
    }
}

/// The level `kind` is set to in `area` in `levels`, if the project set one.
pub fn level(levels: &Levels, kind: ProfileKind, area: Area) -> Option<Level> {
    levels.get(mode_key(kind))?.get(area.key()).copied()
}

/// Applies the levels the project set for `kind` over its default `policy`,
/// as the SandboxScope's classification says: each area set given that
/// level and nothing else of it, the rest of the profile as it was, the
/// run's own files kept. A level past what the sandbox allows refuses.
pub(super) fn apply(
    policy: &mut Policy,
    kind: ProfileKind,
    levels: &Levels,
    areas: &[(Area, Vec<PathBuf>)],
    own: &[PathBuf],
) -> Result<(), Refused> {
    let Some(set) = levels.get(mode_key(kind)) else {
        return Ok(());
    };
    let set: Vec<(Area, Level)> = set
        .iter()
        .filter_map(|(area, level)| Some((Area::of_key(area)?, *level)))
        .collect();
    for (area, level) in &set {
        allowed(kind, *area, *level).map_err(|why| {
            refused(format!(
                "the project gives {} runs {} in {}, which the sandbox never allows. {why}",
                kind.label(),
                level.label(),
                area.label()
            ))
        })?;
    }
    let project = policy.project.clone();
    let paths_of = |area: Area| -> Vec<PathBuf> {
        areas
            .iter()
            .find(|(known, _)| *known == area)
            .map(|(_, paths)| paths.clone())
            .unwrap_or_default()
    };
    let named: Vec<PathBuf> = areas.iter().flat_map(|(_, paths)| paths.clone()).collect();
    // A grant is the rest of the project's where it lies in no named area.
    let is_rest = |path: &Path| path.starts_with(&project) && !named.iter().any(|named| path.starts_with(named));
    let reaches = |grant: &Path, paths: &[PathBuf]| {
        paths.iter().any(|path| path.starts_with(grant) || grant.starts_with(path))
    };
    // What each area gets by default, before anything is changed.
    let defaults: Vec<(Area, Option<Access>)> = areas
        .iter()
        .map(|(area, paths)| {
            let access = policy
                .grants
                .iter()
                .filter(|(grant, _)| grant.starts_with(&project) && reaches(grant, paths))
                .map(|(_, access)| *access)
                .max();
            (*area, access)
        })
        .collect();
    let set_area = |area: Area| set.iter().any(|(known, _)| *known == area);
    for (area, level) in &set {
        let access = match level {
            Level::Edit => Some(Access::ReadWrite),
            Level::Read => Some(Access::ReadOnly),
            Level::NoAccess => None,
        };
        if *area == Area::EverythingElse {
            let removed: Vec<PathBuf> = policy
                .grants
                .iter()
                .filter(|(grant, _)| is_rest(grant) && !own.contains(grant))
                .map(|(grant, _)| grant.clone())
                .collect();
            policy.grants.retain(|(grant, _)| !removed.contains(grant));
            // An area the rest held, not itself set, keeps what it had.
            for (other, default) in &defaults {
                let paths = paths_of(*other);
                if !set_area(*other)
                    && let Some(default) = default
                    && removed.iter().any(|grant| paths.iter().any(|path| path.starts_with(grant)))
                {
                    for path in paths {
                        policy.grants.push((path, *default));
                    }
                }
            }
            if let Some(access) = access {
                policy.grants.push((project.clone(), access));
                // Never reaching the areas but through their own grants.
                for path in &named {
                    if !policy.excluded.contains(path) {
                        policy.excluded.push(path.clone());
                    }
                }
            }
            continue;
        }
        let paths = paths_of(*area);
        policy
            .grants
            .retain(|(grant, _)| own.contains(grant) || !paths.iter().any(|path| grant.starts_with(path)));
        match access {
            Some(access) => {
                for path in &paths {
                    policy.grants.push((path.clone(), access));
                }
            }
            // Denied, but for the project's data, which no wider grant
            // reaches anyway, and an area holding another's grants.
            None if *area != Area::ProjectData => {
                for path in &paths {
                    let holds_grant = policy
                        .grants
                        .iter()
                        .any(|(grant, _)| grant.starts_with(path) && grant != path);
                    if !holds_grant && !policy.denied.contains(path) {
                        policy.denied.push(path.clone());
                    }
                }
            }
            None => {}
        }
    }
    Ok(())
}

